                    </div>
                    <div class="task-date" :class="{ 'overdue': isOverdue(task.due_date) && task.status !== 'completed' }">
                      <el-icon><Clock /></el-icon>
                      <span>{{ task.due_date || '未设置' }}</span>
                    </div>
                  </div>
                </div>
              </div>
              <div v-if="col.tasks.length === 0" class="empty-column">
                <el-empty :image-size="50" description="暂无任务" />
              </div>
            </div>
          </div>
        </div>

        <!-- 列表视图 -->
        <div v-else class="list-view">
          <el-table :data="filteredTasks" style="width: 100%" class="task-table desktop-table" stripe>
            <el-table-column label="优先级" width="100" align="center">
              <template #default="{ row }">
