                  {{ getPriorityText(row.priority) }}
                </el-tag>
              </template>
            </el-table-column>
            <el-table-column prop="title" label="任务标题" min-width="200" />
            <el-table-column prop="assignee_name" label="负责人" width="120" align="center" />
            <el-table-column label="状态" width="120" align="center">
              <template #default="{ row }">
                <el-tag :type="getStatusType(row.status)" size="small">{{ getStatusText(row.status) }}</el-tag>
              </template>
            </el-table-column>
            <el-table-column prop="due_date" label="截止日期" width="150" align="center" />
            <el-table-column label="操作" width="140" fixed="right" align="center">
              <template #default="{ row }">
                <el-button link type="primary" class="action-btn" @click="openTaskDetailDialog(row)">详情</el-button>
                <el-dropdown @command="(cmd) => handleStatusCommand(row, cmd)">
                  <el-button link type="primary" class="action-btn">
                    状态 <el-icon class="el-icon--right"><ArrowDown /></el-icon>
                  </el-button>
                  <template #dropdown>
                    <el-dropdown-menu>
                      <el-dropdown-item command="pending">待处理</el-dropdown-item>
                      <el-dropdown-item command="in_progress">进行中</el-dropdown-item>
                      <el-dropdown-item command="completed">已完成</el-dropdown-item>
                    </el-dropdown-menu>
                  </template>
                </el-dropdown>
              </template>
            </el-table-column>
          </el-table>

          <div v-if="filteredTasks.length > 0" class="mobile-manager-list">
            <div
              v-for="task in filteredTasks"
              :key="task.id"
              class="mobile-manager-card"
              @click="openTaskDetailDialog(task)"
            >
              <div class="mobile-manager-top">
                <h3 class="mobile-manager-title">{{ task.title }}</h3>
                <el-tag :type="getStatusType(task.status)" size="small">{{ getStatusText(task.status) }}</el-tag>
              </div>
              <p class="mobile-manager-desc">{{ task.description || '暂无描述' }}</p>
              <div class="mobile-manager-meta">
                <span>负责人：{{ task.assignee_name || '未分配' }}</span>
                <span>优先级：{{ getPriorityText(task.priority) }}</span>
                <span :class="{ overdue: isOverdue(task.due_date) && task.status !== 'completed' }">
                  截止：{{ task.due_date || '未设置' }}
                </span>
              </div>
              <div class="mobile-manager-actions" @click.stop>
                <el-button size="small" plain @click="openTaskDetailDialog(task)">详情</el-button>
                <el-button
                  size="small"
                  :type="task.status === 'pending' ? 'primary' : 'default'"
                  plain
                  @click="handleStatusCommand(task, 'pending')"
                >
                  待处理
                </el-button>
                <el-button
                  size="small"
                  :type="task.status === 'in_progress' ? 'primary' : 'default'"
                  plain
                  @click="handleStatusCommand(task, 'in_progress')"
                >
                  进行中
                </el-button>
                <el-button
                  size="small"
                  :type="task.status === 'completed' ? 'success' : 'default'"
                  plain
                  @click="handleStatusCommand(task, 'completed')"
                >
                  已完成
                </el-button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </template>

    <!-- 学生视角 -->
    <template v-else>
      <div class="page-header">
        <div class="title-section">
          <div class="title-icon success">
            <el-icon :size="22" color="#67C23A"><List /></el-icon>
          </div>
          <h2>我的任务</h2>
        </div>
        <div class="header-stats">
          <div class="stat-card">
            <div class="stat-value pending">{{ pendingCount }}</div>
            <div class="stat-label">待处理</div>
          </div>
          <div class="stat-card">
            <div class="stat-value in-progress">{{ inProgressCount }}</div>
            <div class="stat-label">进行中</div>
          </div>
          <div class="stat-card">
            <div class="stat-value completed">{{ completedCount }}</div>
            <div class="stat-label">已完成</div>
          </div>
        </div>
      </div>

      <div class="filter-bar">
        <div class="filter-item search-wide">
          <el-input
            v-model="searchKeyword"
            placeholder="搜索任务标题..."
            :prefix-icon="Search"
            clearable
            @change="fetchTasks"
            class="search-input"
          />
        </div>
        <div class="filter-item">
          <el-select v-model="statusFilter" placeholder="任务状态" clearable style="width: 100%">
            <el-option label="全部状态" value="" />
            <el-option label="待处理" value="pending" />
            <el-option label="进行中" value="in_progress" />
            <el-option label="已完成" value="completed" />
          </el-select>
        </div>
      </div>

      <div class="tasks-content mt-4">
        <div v-loading="loading" class="task-list-wrapper">
          <div v-if="filteredStudentTasks.length === 0" class="empty-state">
            <div class="empty-icon">
              <el-icon :size="64" color="#dcdfe6"><CircleCheck /></el-icon>
            </div>
            <p class="empty-text">暂无任务，继续保持！</p>
          </div>

          <div v-else class="task-list">
            <div
              v-for="task in filteredStudentTasks"
              :key="task.id"
              class="task-item"
              :class="{ completed: task.status === 'completed' }"
            >
              <div class="task-priority" :class="task.priority"></div>
              <div class="task-main">
                <div class="task-header">
                  <h3 class="task-title">{{ task.title }}</h3>
                  <el-tag :type="getStatusType(task.status)" size="small" effect="light">
                    {{ getStatusText(task.status) }}
                  </el-tag>
                </div>
                <p class="task-desc">{{ task.description || '暂无描述' }}</p>
                <div class="task-meta">
                  <span v-if="task.due_date" class="meta-item" :class="{ overdue: isOverdue(task.due_date) && task.status !== 'completed' }">
                    <el-icon><Clock /></el-icon>
                    {{ task.due_date }}
                  </span>
                  <span class="meta-item">
                    <el-icon><Flag /></el-icon>
                    {{ getPriorityText(task.priority) }}
                  </span>
                </div>
              </div>
              <div class="task-actions">
                <template v-if="task.status === 'pending'">
                  <el-button type="primary" plain size="small" class="action-button" @click="updateStatus(task, 'in_progress')">
                    开始执行
                  </el-button>
                </template>
                <template v-else-if="task.status === 'in_progress'">
                  <el-button type="success" plain size="small" class="action-button" @click="updateStatus(task, 'completed')">
                    完成
                  </el-button>
                </template>
                <template v-else>
                  <el-tag type="success" effect="plain" class="completed-tag">已完成</el-tag>
                </template>
              </div>
            </div>
          </div>
        </div>
      </div>
    </template>

    <!-- 创建/编辑任务对话框 -->
    <el-dialog
      v-model="dialogVisible"
      :title="isEdit ? '编辑任务' : '新建任务'"
      width="550px"
      class="task-dialog"
      destroy-on-close
    >
      <el-form :model="taskForm" label-width="80px" label-position="top" class="task-form">
        <el-form-item label="任务标题" required>
          <el-input v-model="taskForm.title" placeholder="请输入任务标题" />
        </el-form-item>
        <el-row :gutter="20">
          <el-col :span="12">
            <el-form-item label="负责人" required>
              <el-select v-model="taskForm.assignee" placeholder="请选择负责人" style="width: 100%">
                <el-option v-for="user in users" :key="user.id" :label="user.name" :value="user.id" />
              </el-select>
            </el-form-item>
          </el-col>
          <el-col :span="12">
            <el-form-item label="优先级" required>
              <el-select v-model="taskForm.priority" style="width: 100%">
                <el-option label="高优先级" value="high" />
                <el-option label="中优先级" value="medium" />
                <el-option label="低优先级" value="low" />
              </el-select>
            </el-form-item>
          </el-col>
        </el-row>
        <el-row :gutter="20">
          <el-col :span="12">
