          />
        </el-form-item>
      </el-form>
      <template #footer>
        <div class="dialog-footer">
          <el-button @click="dialogVisible = false">取消</el-button>
          <el-button type="primary" @click="saveTask" :loading="saving">保存任务</el-button>
        </div>
      </template>
    </el-dialog>
  </div>
</template>

<script setup>
import { ref, computed, onMounted, watch } from 'vue'
import { Plus, Search, Calendar, Clock, ArrowDown, List, Flag, Grid, CircleCheck } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import api from '../api'
import dayjs from 'dayjs'

const currentUser = ref(null)

const isManager = computed(() => {
  return currentUser.value && ['管理员', '教师'].includes(currentUser.value.role)
})

const viewMode = ref('kanban')
const tasks = ref([])
const users = ref([])
const searchKeyword = ref('')
const priorityFilter = ref('')
const assigneeFilter = ref('')
const dialogVisible = ref(false)
const isEdit = ref(false)
const saving = ref(false)
const loading = ref(false)
const statusFilter = ref('')

const taskForm = ref({
  id: null,
  title: '',
  description: '',
  assignee: '',
  priority: 'medium',
  status: 'pending',
  due_date: ''
})

const kanbanColumns = computed(() => [
  { title: '待处理', status: 'pending', tasks: filteredTasks.value.filter(t => t.status === 'pending') },
  { title: '进行中', status: 'in_progress', tasks: filteredTasks.value.filter(t => t.status === 'in_progress') },
  { title: '已完成', status: 'completed', tasks: filteredTasks.value.filter(t => t.status === 'completed') }
])

const filteredTasks = computed(() => {
  return tasks.value.filter(t => {
    const keywordMatch = !searchKeyword.value ||
      t.title.toLowerCase().includes(searchKeyword.value.toLowerCase()) ||
      (t.description && t.description.toLowerCase().includes(searchKeyword.value.toLowerCase()))
    const priorityMatch = !priorityFilter.value || t.priority === priorityFilter.value
    const assigneeMatch = !assigneeFilter.value || t.assignee === assigneeFilter.value
    return keywordMatch && priorityMatch && assigneeMatch
  })
})

const filteredStudentTasks = computed(() => {
  return tasks.value.filter(t => {
    const keywordMatch = !searchKeyword.value ||
      t.title.toLowerCase().includes(searchKeyword.value.toLowerCase())
    const statusMatch = !statusFilter.value || t.status === statusFilter.value
    return keywordMatch && statusMatch
  })
})

const pendingCount = computed(() => tasks.value.filter(t => t.status === 'pending').length)
const inProgressCount = computed(() => tasks.value.filter(t => t.status === 'in_progress').length)
const completedCount = computed(() => tasks.value.filter(t => t.status === 'completed').length)

const fetchTasks = async () => {
  loading.value = true
  try {
    let res
    if (isManager.value) {
      res = await api.getTasks()
      tasks.value = res.data.results || res.data || []
    } else {
      res = await api.getMyTasks()
      tasks.value = res.data.results || res.data || []
    }
  } catch (error) {
    ElMessage.error('获取任务失败')
  } finally {
    loading.value = false
  }
}

const fetchUsers = async () => {
  try {
    const res = await api.getProfiles()
    users.value = res.data.results || res.data || []
  } catch (error) {
    ElMessage.error('获取用户列表失败')
  }
}

const openCreateTaskDialog = () => {
  isEdit.value = false
  taskForm.value = {
    id: null,
    title: '',
    description: '',
    assignee: '',
    priority: 'medium',
    status: 'pending',
    due_date: dayjs().add(3, 'day').format('YYYY-MM-DD')
  }
  dialogVisible.value = true
}

const openTaskDetailDialog = (task) => {
  isEdit.value = true
  taskForm.value = { ...task }
  dialogVisible.value = true
}

const saveTask = async () => {
  if (!taskForm.value.title || !taskForm.value.assignee) {
    ElMessage.warning('请填写必填项')
    return
  }

  saving.value = true
  try {
    const assigneeId = Number(taskForm.value.assignee)
    const payload = {
      title: taskForm.value.title,
      description: taskForm.value.description || '',
      assignee: assigneeId,
      priority: taskForm.value.priority || 'medium',
      status: taskForm.value.status || 'pending',
      due_date: taskForm.value.due_date || ''
    }
    if (isEdit.value) {
      await api.updateTask(taskForm.value.id, payload)
      ElMessage.success('更新成功')
    } else {
      await api.createTask(payload)
      ElMessage.success('创建成功')
    }
    dialogVisible.value = false
    fetchTasks()
  } catch (error) {
    ElMessage.error(api.getErrorMessage(error, '保存失败'))
  } finally {
    saving.value = false
  }
}

const handleStatusCommand = async (task, status) => {
  try {
    await api.updateTask(task.id, { status })
    fetchTasks()
  } catch (error) {
    ElMessage.error(api.getErrorMessage(error, '状态更新失败'))
  }
}

let draggedTask = null
const handleDragStart = (e, task) => {
  draggedTask = task
  e.dataTransfer.effectAllowed = 'move'
}

const handleDrop = async (e, newStatus) => {
  if (draggedTask && draggedTask.status !== newStatus) {
    try {
      await api.updateTask(draggedTask.id, { status: newStatus })
      fetchTasks()
    } catch (error) {
      ElMessage.error(api.getErrorMessage(error, '移动任务失败'))
    }
  }
  draggedTask = null
}

const updateStatus = async (task, newStatus) => {
  try {
    await api.updateTask(task.id, { status: newStatus })
    ElMessage.success(newStatus === 'in_progress' ? '任务已开始' : '任务已完成')
    fetchTasks()
  } catch (error) {
    ElMessage.error(api.getErrorMessage(error, '状态更新失败'))
  }
}

const isOverdue = (date) => {
  if (!date) return false
  return dayjs().isAfter(dayjs(date), 'day')
}

const getPriorityText = (p) => ({ high: '高', medium: '中', low: '低' }[p] || p)
const getPriorityType = (p) => ({ high: 'danger', medium: 'warning', low: 'info' }[p] || 'info')
const getStatusText = (s) => ({ pending: '待处理', in_progress: '进行中', completed: '已完成' }[s] || s)
const getStatusType = (s) => ({ pending: 'info', in_progress: 'primary', completed: 'success' }[s] || 'info')

onMounted(() => {
  const userStr = localStorage.getItem('user')
  if (userStr) {
    currentUser.value = JSON.parse(userStr)
  }
  fetchTasks()
  fetchUsers()
})

watch(statusFilter, () => {})
</script>

